package cn.cccs7.cynexus.market.application.controller; import cn.cccs7.cynexus.common.core.result.Result; import cn.cccs7.cynexus.market.api.dto.PortfolioTradePlanDTO; import cn.cccs7.cynexus.market.api.request.PortfolioTradePlanRequest; import cn.cccs7.cynexus.market.application.service.PortfolioTradePlanAppService; import java.util.List; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/market/portfolio/trade-plans") public class PortfolioTradePlanController { private final PortfolioTradePlanAppService service; public PortfolioTradePlanController(PortfolioTradePlanAppService s){service=s;} @GetMapping public Result<List<PortfolioTradePlanDTO>> list(@RequestParam(required=false) String symbol){return Result.success(service.list(symbol));} @PostMapping public Result<PortfolioTradePlanDTO> save(@RequestBody PortfolioTradePlanRequest r){return Result.success(service.save(r));} }
